"""Ordinary user-facing SOL UI and real timer; no soak/controller hooks."""
import argparse,json,unittest
from pathlib import Path
from test_production_clock import ProductionClock
from test_continuity import RecordedResult
class CommandInterface(ProductionClock):
    def go(self,p,page,tab=None):
        p.locator(f'#icarus-menu [data-page="{page}"]').click()
        if tab:p.locator(f'#page-{page} .command-subnav [data-subtab="{tab}"]').click()
    def test_home_is_default_and_widgets_keep_same_live_nodes_and_preferences(self):
        p=self.start('2026-11-09T12:00:00');self.assertTrue(p.locator('#icarus-home').is_visible());p.evaluate('window.originalCrew=document.querySelector("#crew")');p.locator('#home-edit').click();p.locator('[data-widget="cameras"]').check();self.go(p,'operations');self.go(p,'home');self.assertTrue(p.evaluate('window.originalCrew===document.querySelector("#crew")'));p.reload();p.wait_for_function('document.querySelector("#status").textContent.includes("LIVE")');self.assertTrue(p.locator('[data-widget-id="cameras"]').is_visible());self.assertEqual(p.locator('#crew').count(),1)
    def test_tabs_are_isolated_unique_and_browser_back_preserves_navigation(self):
        p=self.start('2026-11-09T12:00:00');self.assertEqual(p.locator('#icarus-menu button').all_text_contents(),['Home','Bridge','Ship','Crew','Missions','Research','Chronicles','Settings']);self.go(p,'ship','systems');self.assertTrue(p.locator('#area-ship-systems').is_visible());self.go(p,'research','evidence');self.assertFalse(p.locator('#area-ship-systems').is_visible());p.go_back();self.assertTrue(p.locator('#area-research-projects').is_visible());p.go_back();self.assertTrue(p.locator('#area-ship-systems').is_visible());self.assertEqual(p.evaluate('()=>{const a=[...document.querySelectorAll("[id]")].map(e=>e.id);return a.length-new Set(a).size;}'),0)
    def test_directives_are_sourced_and_release_is_scoped(self):
        p=self.start('2026-11-09T12:00:00');self.go(p,'operations');p.locator('[data-nav="hold"]').click();p.wait_for_function('document.querySelector("#command-authority").textContent==="DIRECTIVE ACTIVE"');s=self.state(p);self.assertTrue(s['navigation']['hold']);self.assertTrue(any(r.get('data',{}).get('controlLayer')=='operator' for r in s['chronicle']['records']));p.locator('#command-release').click();self.assertEqual(p.locator('#command-authority').inner_text(),'AUTONOMOUS');self.assertFalse(self.state(p)['navigation']['hold'])
    def test_real_20x_timer_pause_normal_and_reload(self):
        p=self.start('2026-11-09T12:00:00');self.go(p,'settings','testing');p.on('dialog',lambda d:d.accept());p.locator('#test-rate').select_option('20');p.clock.fast_forward(30000);self.assertEqual(self.state(p)['tick'],10);self.assertTrue(p.locator('#command-test').is_visible());p.locator('#pause').click();p.clock.fast_forward(30000);self.assertEqual(self.state(p)['tick'],10);p.locator('#pause').click();p.locator('#test-rate').select_option('0');p.clock.fast_forward(15000);self.assertEqual(self.state(p)['tick'],11);self.assertFalse(p.locator('#command-test').is_visible());p.locator('#test-rate').select_option('20');p.clock.fast_forward(3000);self.assertEqual(self.state(p)['tick'],12);p.reload();p.wait_for_function('document.querySelector("#status").textContent.includes("LIVE")');self.assertEqual(p.locator('#test-rate').input_value(),'0');p.clock.fast_forward(15000);self.assertEqual(self.state(p)['tick'],13)
    def test_20x_crosses_real_monday_once_with_same_people(self):
        p=self.start('2026-11-09T05:59:30');self.go(p,'settings','testing');p.on('dialog',lambda d:d.accept());before=self.state(p);p.locator('#test-rate').select_option('20');p.clock.fast_forward(60000);after=self.state(p);self.assertEqual(after['tick'],20);self.assertEqual(after['episode'],before['episode']+1);self.assertEqual([q['name'] for q in before['crew']],[q['name'] for q in after['crew']]);self.assertEqual(len(after['archived']),1)
    def test_20x_holiday_then_normal_one_times(self):
        p=self.start('2026-11-11T05:59:30');self.go(p,'settings','testing');p.on('dialog',lambda d:d.accept());p.locator('#test-rate').select_option('20');p.clock.fast_forward(60000);s=self.state(p);self.assertEqual(s['tick'],20);self.assertEqual(len(s['calendar']['occurrences']),1);p.locator('#test-rate').select_option('0');p.clock.fast_forward(60000);self.assertEqual(self.state(p)['tick'],21);self.assertIn('1×',p.locator('#speed').inner_text())
    def test_test_warning_cancel_and_deliberate_reset_confirmation(self):
        p=self.start('2026-11-09T12:00:00');self.go(p,'settings','testing');p.on('dialog',lambda d:d.dismiss());p.locator('#test-rate').select_option('20');self.assertEqual(p.locator('#test-rate').input_value(),'0');before=self.state(p);p.locator('#reset').click();after=self.state(p);self.assertEqual(after['crew'],before['crew']);self.assertEqual(after['economy'],before['economy']);self.assertEqual(after['tick'],before['tick']);self.assertEqual(after['episode'],before['episode'])
    def test_all_major_pages_responsive_and_rectangular_gradients(self):
        p=self.start('2026-11-09T12:00:00');out=Path('/workspace/work/phase4_reports/screenshots');out.mkdir(exist_ok=True)
        for size,label in [({'width':1920,'height':1080},'desktop'),({'width':1280,'height':800},'tablet'),({'width':1024,'height':768},'narrow')]:
            p.set_viewport_size(size)
            for page in ['home','operations','ship','personnel','missions','research','records','settings']:
                self.go(p,page);p.mouse.move(0,0);p.screenshot(path=str(out/f'{label}_{page}.png'));self.assertLessEqual(p.evaluate('document.documentElement.scrollWidth'),size['width']);b=p.locator('#icarus-menu .active');self.assertEqual(b.evaluate('e=>getComputedStyle(e).clipPath'),'none');self.assertIn('gradient',b.evaluate('e=>getComputedStyle(e).backgroundImage'));self.assertEqual(b.evaluate('e=>getComputedStyle(e).filter'),'none')
        self.go(p,'missions','destinations');self.assertEqual(p.locator('[data-location=derelict]').evaluate('e=>getComputedStyle(e).clipPath'),'none');self.assertGreaterEqual(p.locator('[data-location=derelict]').bounding_box()['height'],44)
    def test_keyboard_navigation_help_and_return_to_home(self):
        p=self.start('2026-11-09T12:00:00');p.locator('#icarus-menu [data-page=home]').focus();p.keyboard.press('ArrowRight');self.assertTrue(p.locator('#page-operations').is_visible());p.keyboard.press('End');self.assertTrue(p.locator('#page-settings').is_visible());p.locator('#command-tour').click();self.assertTrue(p.locator('#command-guidance').evaluate('e=>e.open'));p.locator('#command-tour-done').click();self.assertFalse(p.locator('#command-guidance').evaluate('e=>e.open'))
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--report',default='command_interface.json');args=ap.parse_args();suite=unittest.defaultTestLoader.loadTestsFromTestCase(CommandInterface);r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(suite);Path(args.report).write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d} for t,d in r.failures],'errors':[{'test':str(t),'detail':d} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
